<?php
declare(strict_types=1);
require dirname(__DIR__).'/private/TelegramBot.php';require dirname(__DIR__).'/private/PaymentService.php';
use BotanikArt\{TelegramBot,TelegramFailure,OrderStore,MerchantOrders};
$root=sys_get_temp_dir().'/ba-bot-'.bin2hex(random_bytes(5));$private=$root.'/public/api/.private';mkdir($private,0700,true);mkdir($root.'/public/data',0700,true);
$config=['token'=>'fixture','username'=>'botanikart_fixture_bot','owner_username'=>'Ekaterina_Freed','site_url'=>'https://botanikart.ru','context_secret'=>str_repeat('a',64),'webhook_secret'=>str_repeat('b',64)];$calls=[];$failPhoto=false;
$transport=function($method,$body)use(&$calls,&$failPhoto){if($method==='sendPhoto'&&$failPhoto){$failPhoto=false;throw new TelegramFailure(400);}$calls[]=[$method,$body];return ['message_id'=>count($calls)];};
$bot=new TelegramBot($config,$private,$transport);$checks=0;
function ok($pass,$reason){global $checks;if(!$pass)throw new RuntimeException($reason);$checks++;}
$update=function($id,$text,$chat=101,$username='buyer'){return ['update_id'=>$id,'message'=>['chat'=>['id'=>$chat,'type'=>'private'],'from'=>['id'=>$chat,'username'=>$username],'text'=>$text]];};
try{
 file_put_contents($root.'/public/index.html','<p class="hero-description">Текст с сайта: выращиваем растения.</p>');
 $plant=['id'=>'flowwow-1','title'=>'Маранта','price'=>450,'description'=>'Растение для дома','available'=>true,'status'=>'ready','catalogGroup'=>'potted','images'=>['assets/maranta.jpg']];
 file_put_contents($root.'/public/data/catalog.json',json_encode(['products'=>[$plant,array_replace($plant,['id'=>'flowwow-2','catalogGroup'=>'material','title'=>'Грунт'])],'featured'=>[]]));
 $bot->accept($update(1,'/start'));$bot->drain();ok(str_contains($calls[0][1]['text'],'Текст с сайта'),'Greeting follows website');ok(count($calls[0][1]['reply_markup']['inline_keyboard'])===3,'All catalog sections available');
 $bot->accept($update(1,'/start'));$bot->drain();ok(count($calls)===1,'Duplicate webhook does not repeat messages');
 $callback=['update_id'=>2,'callback_query'=>['id'=>'query1','from'=>['id'=>101,'username'=>'buyer'],'message'=>['chat'=>['id'=>101,'type'=>'private']],'data'=>'c:plants:0']];$bot->accept($callback);$bot->drain();$last=end($calls);ok(str_contains($last[1]['text'],'Растения'),'Plants section opens');ok(count($last[1]['reply_markup']['inline_keyboard'][0])===2,'Plant subcategories shown');
 $callback['update_id']=3;$callback['callback_query']['id']='query2';$callback['callback_query']['data']='p:'.substr(hash('sha256','flowwow-1'),0,20);$bot->accept($callback);$bot->drain();$last=end($calls);ok($last[0]==='sendPhoto','Card includes photograph');$url=$last[1]['reply_markup']['inline_keyboard'][0][0]['url'];parse_str(parse_url($url,PHP_URL_QUERY),$query);ok(TelegramBot::verifyContext($query['tg'],'flowwow-1',$config)==='101','Checkout is signed and linked to buyer');
 foreach([[$query['tg'].'x','flowwow-1'],[$query['tg'],'flowwow-2']] as [$token,$id]){try{TelegramBot::verifyContext($token,$id,$config);throw new RuntimeException('Forged context accepted');}catch(InvalidArgumentException){$checks++;}}
 $pair=$bot->pairingLink();parse_str(parse_url($pair,PHP_URL_QUERY),$link);$bot->accept($update(4,'/start '.$link['start'],202,'impostor'));ok($bot->owner()===null,'Wrong username cannot claim owner');$bot->accept($update(5,'/start '.$link['start'],303,'Ekaterina_Freed'));ok($bot->owner()==='303','Owner links with one-time secret and expected identity');$bot->accept($update(6,'/start '.$link['start'],202,'Ekaterina_Freed'));ok($bot->owner()==='303','Consumed owner link cannot replace owner');$bot->drain(10);
 $order=['orderId'=>'ba-'.str_repeat('c',24),'title'=>'Маранта','amount'=>45000,'phone'=>'+79999999999','email'=>'buyer@example.com','paid'=>true,'status'=>'CONFIRMED','testMode'=>false,'telegramChatId'=>'101'];$before=(int)$bot->db->query('SELECT COUNT(*) FROM outbox')->fetchColumn();$bot->enqueuePaid($order);$bot->enqueuePaid($order);ok((int)$bot->db->query('SELECT COUNT(*) FROM outbox')->fetchColumn()===$before+2,'Paid messages deduplicated per order and recipient');$bot->enqueuePaid(array_replace($order,['orderId'=>'demo','testMode'=>true]));$bot->enqueuePaid(array_replace($order,['orderId'=>'unpaid','paid'=>false]));ok((int)$bot->db->query('SELECT COUNT(*) FROM outbox')->fetchColumn()===$before+2,'No DEMO or unpaid alerts');$bot->drain(10);$notices=array_values(array_filter($calls,fn($c)=>str_contains($c[1]['text']??'','Оплачен новый заказ')));ok(count($notices)===1&&$notices[0][1]['chat_id']==='303','Only linked owner receives buyer contacts');
 $bot->accept($update(7,'/orders',101,'buyer'));$bot->drain();ok(!str_contains(end($calls)[1]['text'],'buyer@example.com'),'Customer cannot read owner orders');
 $callback['update_id']=8;$callback['callback_query']['id']='query3';$failPhoto=true;$bot->accept($callback);$bot->drain(4);ok(end($calls)[0]==='sendMessage'&&str_contains(end($calls)[1]['text'],'Маранта'),'Photo failure falls back to readable product card');
 $before=(int)$bot->db->query('SELECT COUNT(*) FROM updates')->fetchColumn();$bad=$update(9,'/start');$bad['message']['chat']['type']='group';$bot->accept($bad);ok((int)$bot->db->query('SELECT COUNT(*) FROM updates')->fetchColumn()===$before,'Group messages ignored');
 echo "Telegram tests passed: $checks assertions.\n";
}finally{$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::CHILD_FIRST);foreach($it as $f)$f->isDir()?rmdir($f->getPathname()):unlink($f->getPathname());rmdir($root);}
